def solve(g):
    h,w=len(g),len(g[0])
    # find 2x2 blocks
    blocks=[(i,j) for i in range(h-1) for j in range(w-1) if g[i][j]==2==g[i][j+1]==g[i+1][j]==g[i+1][j+1]==2]
    out=[[0]*w for _ in range(h)]
    # copy blocks
    for i in range(h):
        for j in range(w):
            if g[i][j]==2: out[i][j]=2
    def blocks_cover(i,j):
        return any(i in range(b[0],b[0]+2) and j in range(b[1],b[1]+2) for b in blocks)
    for i in range(h):
        for j in range(w):
            c=g[i][j]
            if c!=0 and c!=2:
                # nearest block
                d=min(((abs(i-b0)+abs(j-b1)),b) for b in blocks)
                _,b=d
                br,bc=b
                mr,mc=2*br+1-i, 2*bc+1-j   # point reflection through center
                dr=1 if mr>=br else (-1 if mr<=br+1 else 0)
                dc=1 if mc>=bc else (-1 if mc<=bc+1 else 0)
                # direction away from block: from mirrored point outward
                sr,sc=mr,mc
                r,ii=mr+dr,mc+dc
                while 0<=r<h and 0<=ii<w and not blocks_cover(r,ii):
                    out[r][ii]=c; r+=dr; ii+=dc
    return out
