import math, json
def solve(gi):
    h,w=len(gi),len(gi[0])
    seeds=[(i,j,gi[i][j]) for i in range(h) for j in range(w) if gi[i][j] not in (0,2)]
    blocks=[(i,j) for i in range(h) for j in range(w) if gi[i][j]==2]
    rs=[i for i,j in blocks]; cs_=[j for i,j in blocks]
    cr=(min(rs)+max(rs))/2; cc=(min(cs_)+max(cs_))/2
    def slot(i,j):
        dr=-1 if i<cr else (1 if i>cr else 0); dc=-1 if j<cc else (1 if j>cc else 0)
        return (dr<<1)|dc   # 0:TL 1:TR 2:BR 3:BL
    slots={}
    for s in seeds: slots[slot(s[0],s[1])]=s
    order=[s for sl in range(4) for s in [slots.get(sl)]]
    cyc={s[2]:order[(k+1)%4][2] if k<len(order)-1 or len(order)>1 else None for k,s in enumerate([(x[2],x) for x in order])}
    cyc={s[2]:order[(k+1)%len(order)][2] for k,s in enumerate([(o[2],o) for o in order])}
    out=[r[:] for r in gi]
    for i,j,c in seeds:
        dr=1 if i>cr else -1; dc=1 if j>cc else -1
        ri,rj=i+dr,j+dc
        while 0<=ri<h and 0<=rj<w and gi[ri][rj]==0:
            out[ri][rj]=cyc[c]
            ri+=dr; rj+=dc
    for i,j,c in seeds:
        out[i][j]=cyc[c]
    return out
