import math,collections
def solve(gi, both=True, stop=None, priority='cw'):
    h,w=len(gi),len(gi[0])
    seeds=[(i,j,gi[i][j]) for i in range(h) for j in range(w) if gi[i][j] not in (0,2)]
    rs=[s[0] for s in seeds]; cs_=[s[1] for s in seeds]
    cr=(min(rs)+max(rs))/2; cc=(min(cs_)+max(cs_)/2)
    asc=sorted(seeds,key=lambda s:math.atan2(s[0]-cr,s[1]-cc))
    cyc={}
    if priority=='cw':
        # each becomes next CW (prev in ascending): pred wraps around
        for a in range(len(asc)): cyc[asc[a][2]]=asc[(a-1)%len(asc)][2]
    else:
        for a in range(len(asc)): cyc[asc[a][2]]=asc[(a+1)%len(asc)][2]
    out=[r[:] for r in gi]
    dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
    def paint(i0,j0,c):
        for dr,dc in dirs:
            ri,rj=i0+dr,j0+dc
            while 0<=ri<h and 0<=rj<w and gi[ri][rj]==0:
                out[ri][rj]=c
                ri+=dr; rj+=dc
    for s in sorted(seeds,key=lambda s:-math.atan2(s[0]-cr,s[1]-cc)):
        paint(*s[:2],cyc[s[2]])
    for s in seeds: out[s[0]][s[1]]=cyc[s[2]]
    return out
